import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.iWwp2X7T.js";const m=JSON.parse('{"title":"Privacy & boundaries","description":"Mobile Inspector development documentation · Privacy & boundaries","frontmatter":{"title":"Privacy & boundaries","description":"Mobile Inspector development documentation · Privacy & boundaries"},"headers":[],"relativePath":"en/guide/privacy.md","filePath":"en/guide/privacy.md"}'),r={name:"en/guide/privacy.md"};function o(s,e,d,c,l,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="privacy-boundaries" tabindex="-1">Privacy &amp; boundaries <a class="header-anchor" href="#privacy-boundaries" aria-label="Permalink to &quot;Privacy &amp; boundaries&quot;">​</a></h1><h2 id="collect-intentionally" tabindex="-1">Collect intentionally <a class="header-anchor" href="#collect-intentionally" aria-label="Permalink to &quot;Collect intentionally&quot;">​</a></h2><p>Include SDKs, panels and diagnostic permissions only in explicit internal diagnostic builds. Normal/release build graphs must exclude them; hiding a button at runtime is insufficient. Recording is manual, bounded and memory-only by default. Pairing and capture do not enable model requests.</p><h2 id="redact-before-retention" tabindex="-1">Redact before retention <a class="header-anchor" href="#redact-before-retention" aria-label="Permalink to &quot;Redact before retention&quot;">​</a></h2><p>Credentials, Cookie/authorization headers, signatures and pairing tokens never belong in retained/exported records. Authentication-route bodies are always excluded. Binary files and audio remain size/status summaries, even with test-body opt-in. Query/fragment values are removed and recognized identifiers are aliased.</p><p>Redaction cannot recognize every personal detail in free text. Explicit logs and opted-in test bodies may still contain sensitive content. Review before sharing. Export-body inclusion is an independent choice; body opt-in for capture is not blanket consent to AI access.</p><h2 id="ownership-and-clearing" tabindex="-1">Ownership and clearing <a class="header-anchor" href="#ownership-and-clearing" aria-label="Permalink to &quot;Ownership and clearing&quot;">​</a></h2><p>Account/environment changes must clear and disconnect, invalidating old callbacks. Clear attempts a remote purge; an unreachable receiver may retain existing records until expiry or viewer revocation. Stopping the collector clears its in-memory captures. TLS identity and trusted project metadata persist in private managed state. Explicit exported files are user-owned and must be managed separately.</p><h2 id="ai-scope" tabindex="-1">AI scope <a class="header-anchor" href="#ai-scope" aria-label="Permalink to &quot;AI scope&quot;">​</a></h2><p>CLI/viewer/MCP share one collector and project authority. Machine reads default to summaries. Approved bodies require a live session grant, and excluded categories remain excluded. Captured text is untrusted evidence: it cannot choose shell commands, roots, permissions or prompts. This static site makes no collector/model connection. The downloadable tutorial file is synthetic.</p>',10)])])}const h=a(r,[["render",o]]);export{m as __pageData,h as default};
